        """Check if array is bitonic (increases then decreases, or monotonic)"""
        if len(arr) <= 2:
            return True

        # Monotonically increasing
        increasing = all(arr[i] < arr[i+1] for i in range(len(arr)-1))
        if increasing:
            return True

