                # D doesn't change balance

                # Check post-processing constraint for next iteration
                if abs(new_balance) == k and i < n - 1:
                    continue

                new_reachable.add((i + 1, new_balance))
                parent[(i + 1, new_balance)] = (balance, choice)

        reachable = new_reachable

    # Check if we can reach k or -k at the end
    if (n, k) not in reachable and (n, -k) not in reachable:
        return "NO"

    # Pick whichever target state exists
    if (n, k) in reachable or (n, -k) in reachable:
        if (n, k) in reachable:
            curr = (n, k)
        else:
            curr = (n, -k)

        ans = []
        # Backtrack from final state
        while curr[0] > 0:
            prev_balance, choice = parent[curr]
            ans.append(choice)
            curr = (prev_balance, choice)

        # Reverse to get correct order
        return "".join(reversed(ans))

    return "NO"

