def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0])
    MAX_N = 1000000
    MOD = 10**9 + 7

    # Precompute omega (number of distinct prime factors) using sieve
    omega = [0] * (MAX_N + 1)
    for i in range(2, MAX_N + 1):
        if omega[i] == 0:  # i is prime
            for j in range(i, MAX_N + 1, i):
                omega[j] += 1

    # f0[n] = 2^omega[n] modulo MOD
    f0 = [1] * (MAX_N + 1)
    for n in range(MAX_N + 1):
        f0[n] = pow(2, omega[n], MOD)

    # Precompute cumulative results for different r values
    # Based on the problem pattern, fr(n) accumulates f0 values
    MAX_R = 1000000

    # Build answers by precomputing for all possible (r, n) pairs
    # that we might encounter
    answers = [0] * ((MAX_R + 1) * (MAX_N + 1))

    for r in range(MAX_R + 1):
        for n in range(MAX_N + 1):
            if r == 0:
                answers[(r, n)] = f0[n]
            else:
                # For r > 0, compute based on the recursive relationship
                # Pattern: fr(n) = sum of f0(d) for relevant divisors d
                if n == 1:
                    answers[(r, n)] = 1
                else:
                    # Sum f0 over divisors
                    total = 0
                    for d in range(1, n + 1):
                        if n % d == 0:
                            total = (total + f0[d]) % MOD
                    answers[(r, n)] = total

    # Process queries
    line_idx = 1
    output = []
    for _ in range(q):
        r = int(lines[line_idx])
        n = int(lines[line_idx + 1])
        line_idx += 2
        output.append(str(answers[(r, n)]))

    return '\n'.join(output)

