                sn_x = points[i][0] + frac * (points[i+1][0] - points[i][0])
                sn_y = points[i][1] + frac * (points[i+1][1] - points[i][1])
                sn_z = points[i][2] + frac * (points[i+1][2] - points[i][2])
                return sn_x, sn_y, sn_z
            s += seg_len
